def build_lstm_training_arrays(seq_len=16, shuffle=True, seed=42):
    """将1000条字典序列转换为 X=[N,T,16]、y=[N]、lengths=[N]。"""

    sample_count = len(lstm_training_data)
    feature_dim = 16

    X = np.zeros((sample_count, seq_len, feature_dim), dtype=np.float32)
    y = np.zeros(sample_count, dtype=np.float32)
    lengths = np.zeros(sample_count, dtype=np.int32)

    for sample_idx, sequence in enumerate(lstm_training_data):
        extractor = FeatureExtractor()

        actions = sequence["actions"]
        valid_len = min(len(actions), seq_len)

        sequence_id = sequence["sequence_id"]
        session_id = f"session-{sequence_id}"
        run_id = f"run-{sequence_id}"

        for step in range(valid_len):
            sample = actions[step]

            action_type_name = sample["actionType"]
            action_type = ACTION_TYPES[action_type_name]

            trace = {
                "session_id": session_id,
                "run_id": run_id,
                "parent_event_id": "" if step == 0 else f"event-{step - 1}",
            }

            action_content = build_action_content(
                action_type_name,
                sample.get("toolName", ""),
                sample.get("params", {}),
                sample.get("content", ""),
                extra={"trace": trace},
            )

            features, trace_key = extractor.extract_features(
                action_type,
                action_type_name,
                action_content,
            )

            X[sample_idx, step] = features

            # 不使用标签更新历史，避免标签泄漏
            history_score = float(features[15])
            blocked = history_score >= 0.45

            extractor.update_session_history(
                trace_key,
                action_type_name,
                score=history_score,
                blocked=blocked,
            )

        y[sample_idx] = float(sequence["label"])
        lengths[sample_idx] = valid_len

    if shuffle:
        rng = np.random.default_rng(seed)
        order = rng.permutation(sample_count)
        X = X[order]
        y = y[order]
        lengths = lengths[order]

    return X, y, lengths


def get_lstm_training_data():
    return lstm_training_data


if __name__ == "__main__":
    X, y, lengths = build_lstm_training_arrays()

    print("序列总数:", len(lstm_training_data))
    print("正常序列:", int(np.sum(y == 0)))
    print("中毒序列:", int(np.sum(y == 1)))
    print("X.shape:", X.shape)
    print("y.shape:", y.shape)
    print("lengths.shape:", lengths.shape)
    print("有效长度范围:", int(lengths.min()), "~", int(lengths.max()))
